    /**
     * Lazily initializes and returns a data map for ZIP code information.
     *
     * This method uses EnumDataUtils::buildLazyDataMap() to cache ZIP code
     * data extracted from ZipCodeInfo attributes on enum cases.
     *
     * @return array<string, array<string, mixed>> The cached data map
     */
    private static function zipCodeData(): array
    {
        // ---
        // Create a closure to extract ZIP code data from ZipCodeInfo attributes into an
        // associative array
        // ---
        $dataExtractor = fn ($info, $caseValue) => [
            'zip_code' => $info->zip_code,
            'city' => $info->city,
            'state_usps' => $info->state_usps,
            'state_geoId' => $info->state_geoId,
            'county_geoId' => $info->county_geoId,
        ];

        // ---
        // Build and cache the lazy data map using reflection to extract ZipCodeInfo
        // attributes from all enum cases
        // ---
        $result = EnumDataUtils::buildLazyDataMap(
            self::class,
            ZipCodeInfo::class,
            $dataExtractor
        );

        // Clean up variables to free up memory
        unset(
            $dataExtractor
        );

        // Return the cached ZIP code data map
        return $result;
    }

    /**
     * Get the ZIP code.
     *
     * @return string The ZIP code
     */
    public function zipCode(): string
    {
        // Retrieve the cached ZIP code data map
        $data = self::zipCodeData();

        // Extract and return the zip_code field value for this ZIP code
        return EnumDataUtils::getFieldValue(
            $data,
            $this->value,
            'zip_code',
            'ZIP code'
        );
    }

    /**
     * Get the USPS city name.
     *
     * @return string The USPS city name
     */
    public function city(): string
    {
        // Retrieve the cached ZIP code data map
        $data = self::zipCodeData();

        // Extract and return the city field value for this ZIP code
        return EnumDataUtils::getFieldValue(
            $data,
            $this->value,
            'city',
            'ZIP code'
        );
    }

    /**
     * Get the USPS state code.
     *
     * @return string The USPS state code
     */
    public function stateUsps(): string
    {
        // Retrieve the cached ZIP code data map
        $data = self::zipCodeData();

        // Extract and return the state_usps field value for this ZIP code
        return EnumDataUtils::getFieldValue(
            $data,
            $this->value,
            'state_usps',
            'ZIP code'
        );
    }

    /**
     * Get the state GEOID.
     *
     * @return string The state GEOID
     */
    public function stateGeoId(): string
    {
        // Retrieve the cached ZIP code data map
        $data = self::zipCodeData();

        // Extract and return the state_geoId field value for this ZIP code
        return EnumDataUtils::getFieldValue(
            $data,
            $this->value,
            'state_geoId',
            'ZIP code'
        );
    }

    /**
     * Get the county GEOIDs.
     *
     * @return array<string> The county GEOIDs
     */
    public function countyGeoIds(): array
    {
        // Retrieve the cached ZIP code data map
        $data = self::zipCodeData();

        // Get the data entry for this ZIP code
        $zipData = $data[$this->value] ?? throw new \ValueError("Unknown ZIP code: {$this->value}");

        // Return the county_geoId array (getFieldValue is for strings only)
        return $zipData['county_geoId'];
    }

    /**
     * Get all ZIP code information as an array.
     *
     * @return array<string, string|array<string>> All ZIP code information
     */
    public function toArray(): array
    {
        // Retrieve the cached ZIP code data map
        $data = self::zipCodeData();

        // Get the data entry for this ZIP code
        $zipData = $data[$this->value] ?? throw new \ValueError("Unknown ZIP code: {$this->value}");

        // Return the complete data array
        return $zipData;
    }
